import React, { useMemo, useState, useEffect } from "react";
import { User } from "../pages/Users";

interface Column {
  label: string;
  key: keyof User;
}

interface Props {
  data: User[];
  columns: Column[];
  onSort: (key: keyof User) => void;
  sortConfig?: { key: keyof User; direction: "asc" | "desc" } | null;
  rowsPerPage?: number;
  onViewUser?: (user: User) => void;
  onSuspendUser?: (user: User) => void;
}

/* ─── Status ─────────────────────────────────────────────────── */
type Status = "active" | "suspended" | "pending";

function deriveStatus(user: User): Status {
  if (user.location_allowed === true) return "active";
  if (user.location_allowed === false) return "suspended";
  return "pending";
}

const STATUS_STYLES: Record<Status, React.CSSProperties> = {
  active:    { background: "#DCFCE7", color: "#16A34A" },
  suspended: { background: "#FEE2E2", color: "#DC2626" },
  pending:   { background: "#FEF9C3", color: "#CA8A04" },
};

const StatusBadge: React.FC<{ status: Status }> = ({ status }) => (
  <span style={{
    ...STATUS_STYLES[status],
    padding: "3px 12px", borderRadius: 20, fontSize: 12,
    fontWeight: 600, letterSpacing: 0.2, display: "inline-block",
  }}>
    {status.charAt(0).toUpperCase() + status.slice(1)}
  </span>
);

/* ─── Avatar ─────────────────────────────────────────────────── */
const Avatar: React.FC<{ src?: string | null; name: string; size?: number }> = ({ src, name, size = 36 }) => {
  const initials = name.split(" ").map((w) => w[0]).join("").slice(0, 2).toUpperCase();
  return src ? (
    <img src={src} alt={name}
      style={{ width: size, height: size, borderRadius: "50%", objectFit: "cover",
        border: "2px solid rgba(255,255,255,0.15)", flexShrink: 0 }}
      onError={(e) => { (e.currentTarget as HTMLImageElement).style.display = "none"; }}
    />
  ) : (
    <div style={{
      width: size, height: size, borderRadius: "50%", background: "#334155",
      display: "flex", alignItems: "center", justifyContent: "center",
      fontSize: size * 0.36, fontWeight: 700, color: "#94A3B8", flexShrink: 0,
    }}>
      {initials || "?"}
    </div>
  );
};

/* ─── Icon button ────────────────────────────────────────────── */
const IconBtn: React.FC<{ title: string; onClick: (e: React.MouseEvent) => void; children: React.ReactNode }> = ({
  title, onClick, children,
}) => {
  const [hovered, setHovered] = useState(false);
  return (
    <button title={title} onClick={onClick}
      onMouseEnter={() => setHovered(true)} onMouseLeave={() => setHovered(false)}
      style={{
        width: 32, height: 32, border: "1.5px solid #E2E8F0", borderRadius: "50%",
        background: hovered ? "#F8FAFC" : "#fff", cursor: "pointer",
        display: "flex", alignItems: "center", justifyContent: "center",
        transition: "background 0.15s", padding: 0,
      }}
    >
      {children}
    </button>
  );
};

/* ─── Sort icon ──────────────────────────────────────────────── */
const SortIcon: React.FC<{ active: boolean; direction?: "asc" | "desc" }> = ({ active, direction }) => (
  <svg width="13" height="13" viewBox="0 0 13 13" fill="none">
    <path d="M6.5 2v9M6.5 2L4 5M6.5 2L9 5"
      stroke={active && direction === "asc" ? "#EA580C" : "#CBD5E1"}
      strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
    <path d="M6.5 11L4 8M6.5 11L9 8"
      stroke={active && direction === "desc" ? "#EA580C" : "#CBD5E1"}
      strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
  </svg>
);

/* ─── Page button ────────────────────────────────────────────── */
const PageBtn: React.FC<{ label: string; active?: boolean; disabled?: boolean; onClick: () => void }> = ({
  label, active = false, disabled = false, onClick,
}) => (
  <button onClick={onClick} disabled={disabled} style={{
    minWidth: 34, height: 34, borderRadius: 8,
    border: active ? "none" : "1px solid #E2E8F0",
    background: active ? "#EA580C" : disabled ? "#F8FAFC" : "#fff",
    color: active ? "#fff" : disabled ? "#CBD5E1" : "#334155",
    fontWeight: 600, fontSize: 13, cursor: disabled ? "not-allowed" : "pointer",
    padding: "0 8px", transition: "background 0.15s",
  }}>
    {label}
  </button>
);

/* ─── User Detail Drawer ─────────────────────────────────────── */
const InfoRow: React.FC<{ label: string; value?: string | null }> = ({ label, value }) => (
  <div style={{ marginBottom: 16 }}>
    <div style={{ fontSize: 12, color: "#64748B", marginBottom: 3 }}>{label} :</div>
    <div style={{ fontSize: 14, color: value ? "#94A3B8" : "#475569" }}>{value || "—"}</div>
  </div>
);

const Section: React.FC<{ title: string; children: React.ReactNode }> = ({ title, children }) => (
  <div style={{ marginBottom: 24 }}>
    <div style={{ fontSize: 13, fontWeight: 600, color: "#CBD5E1", marginBottom: 12 }}>{title}</div>
    {children}
  </div>
);

const DarkBox: React.FC<{ children: React.ReactNode; minHeight?: number }> = ({ children, minHeight }) => (
  <div style={{
    background: "#0F172A", border: "1px solid #1E293B", borderRadius: 10,
    padding: "14px 16px", minHeight, color: "#94A3B8", fontSize: 14, lineHeight: 1.6,
  }}>
    {children}
  </div>
);

const UserDetailDrawer: React.FC<{ user: User | null; onClose: () => void; onSuspend: (u: User) => void }> = ({
  user, onClose, onSuspend,
}) => {
  // Close on Escape
  useEffect(() => {
    const handler = (e: KeyboardEvent) => { if (e.key === "Escape") onClose(); };
    window.addEventListener("keydown", handler);
    return () => window.removeEventListener("keydown", handler);
  }, [onClose]);

  if (!user) return null;
  const status = deriveStatus(user);

  return (
    <>
      {/* Backdrop */}
      <div onClick={onClose} style={{
        position: "fixed", inset: 0, background: "rgba(0,0,0,0.45)",
        zIndex: 100, backdropFilter: "blur(2px)",
      }} />

      {/* Drawer */}
      <div style={{
        position: "fixed", top: 0, right: 0, bottom: 0,
        width: "min(100vw, 900px)",
        background: "#0A0F1A",
        zIndex: 101,
        overflowY: "auto",
        fontFamily: "'DM Sans', 'Helvetica Neue', sans-serif",
        boxShadow: "-8px 0 40px rgba(0,0,0,0.4)",
        display: "flex", flexDirection: "column",
      }}>

        {/* Close button */}
        <button onClick={onClose} style={{
          position: "absolute", top: 16, right: 16, width: 32, height: 32,
          borderRadius: "50%", border: "1px solid #1E293B", background: "#0F172A",
          color: "#64748B", cursor: "pointer", fontSize: 18, display: "flex",
          alignItems: "center", justifyContent: "center", zIndex: 1,
        }}>×</button>

        <div style={{ display: "flex", gap: 0, flex: 1, flexWrap: "wrap" }}>

          {/* ── LEFT PANEL ── */}
          <div style={{
            width: "min(280px, 100%)", background: "#0F172A",
            borderRight: "1px solid #1E293B", padding: "32px 24px",
            display: "flex", flexDirection: "column", alignItems: "center",
            flexShrink: 0,
          }}>
            <Avatar src={user.image_url} name={user.name} size={88} />
            <div style={{ marginTop: 16, textAlign: "center" }}>
              <div style={{ fontSize: 18, fontWeight: 700, color: "#F1F5F9" }}>{user.name || "—"}</div>
              {user.professional_headline && (
                <div style={{ fontSize: 13, color: "#64748B", marginTop: 4 }}>
                  {user.professional_headline}
                </div>
              )}
              <div style={{ marginTop: 10 }}>
                <StatusBadge status={status} />
              </div>
            </div>

            <div style={{ width: "100%", marginTop: 32, borderTop: "1px solid #1E293B", paddingTop: 24 }}>
              <InfoRow label="Mobile No." value={user.phone} />
              <InfoRow label="Location" value={user.location !== "—" ? user.location : null} />
              <InfoRow label="User Type" value={
                user.user_type_names?.length
                  ? user.user_type_names.map(t => t.charAt(0).toUpperCase() + t.slice(1)).join(", ")
                  : null
              } />
              <InfoRow label="Joined" value={
                user.created_at
                  ? new Date(user.created_at).toLocaleDateString("en-GB", { year: "numeric", month: "long", day: "numeric" })
                  : null
              } />
            </div>

            {/* Suspend / Unsuspend */}
            <button
              onClick={() => onSuspend(user)}
              style={{
                marginTop: "auto", paddingTop: 32, width: "100%",
                padding: "10px 0", borderRadius: 10, border: "none",
                background: status === "suspended" ? "#166534" : "#7F1D1D",
                color: status === "suspended" ? "#86EFAC" : "#FCA5A5",
                fontWeight: 600, fontSize: 14, cursor: "pointer",
                fontFamily: "inherit",
              }}
            >
              {status === "suspended" ? "Unsuspend User" : "Suspend User"}
            </button>
          </div>

          {/* ── RIGHT PANEL ── */}
          <div style={{ flex: 1, padding: "32px 28px", minWidth: 0 }}>

            {/* About */}
            <Section title="About">
              <DarkBox minHeight={80}>
                {user.about_me || <span style={{ color: "#334155" }}>No bio provided.</span>}
              </DarkBox>
            </Section>

            {/* Skills + Certifications */}
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 20, marginBottom: 24 }}>
              <Section title="Skills">
                <DarkBox minHeight={100}>
                  {user.skills_id?.length
                    ? user.skills_id.join(", ")
                    : <span style={{ color: "#334155" }}>No skills listed.</span>}
                </DarkBox>
              </Section>
              <Section title="Certifications">
                <DarkBox minHeight={100}>
                  {user.certifications?.length ? (
                    user.certifications.map((cert, i) => (
                      <div key={i} style={{
                        display: "flex", justifyContent: "space-between",
                        alignItems: "center", marginBottom: i < user.certifications.length - 1 ? 10 : 0,
                      }}>
                        <span style={{ color: "#CBD5E1" }}>{cert}</span>
                        <span style={{
                          fontSize: 10, fontWeight: 700, padding: "2px 6px",
                          background: "#7F1D1D", color: "#FCA5A5", borderRadius: 4,
                        }}>PDF</span>
                      </div>
                    ))
                  ) : <span style={{ color: "#334155" }}>No certifications.</span>}
                </DarkBox>
              </Section>
            </div>

            {/* Profile Attachments */}
            {user.profile_attachments?.length > 0 && (
              <Section title="Profile Attachments">
                <div style={{ display: "flex", flexWrap: "wrap", gap: 10 }}>
                  {user.profile_attachments.map((url, i) => (
                    <a key={i} href={url} target="_blank" rel="noreferrer" style={{
                      display: "flex", alignItems: "center", gap: 8,
                      padding: "8px 14px", background: "#0F172A",
                      border: "1px solid #1E293B", borderRadius: 8,
                      color: "#60A5FA", fontSize: 13, textDecoration: "none",
                    }}>
                      📎 Attachment {i + 1}
                    </a>
                  ))}
                </div>
              </Section>
            )}

            {/* Raw IDs info */}
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 20 }}>
              <Section title="Location IDs">
                <DarkBox>
                  {user.location_id?.length
                    ? user.location_names?.join(", ") || user.location_id.join(", ")
                    : <span style={{ color: "#334155" }}>—</span>}
                </DarkBox>
              </Section>
              <Section title="User Type">
                <DarkBox>
                  {user.user_type_names?.length
                    ? user.user_type_names.map(t => t.charAt(0).toUpperCase() + t.slice(1)).join(", ")
                    : <span style={{ color: "#334155" }}>—</span>}
                </DarkBox>
              </Section>
              <Section title="Phone">
                <DarkBox>{user.phone || <span style={{ color: "#334155" }}>—</span>}</DarkBox>
              </Section>
            </div>

          </div>
        </div>
      </div>
    </>
  );
};

/* ─── Mobile Card ────────────────────────────────────────────── */
const MobileCard: React.FC<{ user: User; idx: number; onRowClick: (u: User) => void; onSuspend: (u: User) => void }> = ({
  user, idx, onRowClick, onSuspend,
}) => {
  const status = deriveStatus(user);
  return (
    <div
      onClick={() => onRowClick(user)}
      style={{
        background: "#fff", border: "1px solid #E8EDF2", borderRadius: 12,
        padding: "16px", marginBottom: 10, cursor: "pointer",
        boxShadow: "0 1px 3px rgba(15,23,42,0.05)",
      }}
    >
      <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 12 }}>
        <span style={{ fontSize: 12, color: "#94A3B8", minWidth: 24 }}>
          {String(idx).padStart(2, "0")}
        </span>
        <Avatar src={user.image_url} name={user.name} />
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontWeight: 600, fontSize: 14, color: "#0F172A", whiteSpace: "nowrap",
            overflow: "hidden", textOverflow: "ellipsis" }}>{user.name || "—"}</div>
          {user.professional_headline && (
            <div style={{ fontSize: 11, color: "#94A3B8", whiteSpace: "nowrap",
              overflow: "hidden", textOverflow: "ellipsis" }}>{user.professional_headline}</div>
          )}
        </div>
        <StatusBadge status={status} />
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8, fontSize: 13 }}>
        <div><span style={{ color: "#94A3B8" }}>Location: </span><span style={{ color: "#475569" }}>{user.location}</span></div>
        <div><span style={{ color: "#94A3B8" }}>Phone: </span><span style={{ color: "#475569" }}>{user.phone || "—"}</span></div>
        <div><span style={{ color: "#94A3B8" }}>Type: </span><span style={{ color: "#475569" }}>
          {user.user_type_names?.map(t => t.charAt(0).toUpperCase() + t.slice(1)).join(", ") || "—"}
        </span></div>
        <div><span style={{ color: "#94A3B8" }}>Joined: </span><span style={{ color: "#475569" }}>
          {user.created_at ? new Date(user.created_at).toLocaleDateString("en-GB") : "—"}
        </span></div>
      </div>
      <div style={{ display: "flex", gap: 8, marginTop: 12, justifyContent: "flex-end" }}>
        <IconBtn title="Suspend" onClick={(e) => { e.stopPropagation(); onSuspend(user); }}>
          <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
            <circle cx="8" cy="8" r="7" stroke="#94A3B8" strokeWidth="1.5" />
            <path d="M3.5 3.5l9 9" stroke="#94A3B8" strokeWidth="1.5" strokeLinecap="round" />
          </svg>
        </IconBtn>
      </div>
    </div>
  );
};

/* ─── Main ───────────────────────────────────────────────────── */
export const UserTable: React.FC<Props> = ({
  data, columns, onSort, sortConfig,
  rowsPerPage = 10,
  onViewUser, onSuspendUser,
}) => {
  const [currentPage, setCurrentPage] = useState(1);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [selectedUser, setSelectedUser] = useState<User | null>(null);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 768);

  useEffect(() => {
    const handler = () => setIsMobile(window.innerWidth < 768);
    window.addEventListener("resize", handler);
    return () => window.removeEventListener("resize", handler);
  }, []);

  const totalPages = Math.max(1, Math.ceil(data.length / rowsPerPage));

  const paginatedData = useMemo(() => {
    const start = (currentPage - 1) * rowsPerPage;
    return data.slice(start, start + rowsPerPage);
  }, [data, currentPage, rowsPerPage]);

  const allSelected = paginatedData.length > 0 && paginatedData.every((u) => selectedIds.has(u.id));

  const toggleAll = () => setSelectedIds((prev) => {
    const next = new Set(prev);
    if (allSelected) paginatedData.forEach((u) => next.delete(u.id));
    else paginatedData.forEach((u) => next.add(u.id));
    return next;
  });

  const toggleOne = (id: string) => setSelectedIds((prev) => {
    const next = new Set(prev);
    next.has(id) ? next.delete(id) : next.add(id);
    return next;
  });

  const pageNumbers = useMemo(() => {
    if (totalPages <= 5) return Array.from({ length: totalPages }, (_, i) => i + 1);
    if (currentPage <= 3) return [1, 2, 3, 4, 5];
    if (currentPage >= totalPages - 2)
      return [totalPages - 4, totalPages - 3, totalPages - 2, totalPages - 1, totalPages];
    return [currentPage - 2, currentPage - 1, currentPage, currentPage + 1, currentPage + 2];
  }, [currentPage, totalPages]);

  const handleRowClick = (user: User) => {
    setSelectedUser(user);
    onViewUser?.(user);
  };

  const sortTh = (key: keyof User, label: string) => (
    <th style={{ ...thBase, cursor: "pointer" }} onClick={() => onSort(key)}>
      <div style={thInner}>
        {label}
        <SortIcon active={sortConfig?.key === key}
          direction={sortConfig?.key === key ? sortConfig.direction : undefined} />
      </div>
    </th>
  );

  const pagination = totalPages > 1 && (
    <div style={{
      padding: "14px 20px", borderTop: "1px solid #F1F5F9",
      display: "flex", justifyContent: "space-between",
      alignItems: "center", flexWrap: "wrap", gap: 12,
    }}>
      <span style={{ fontSize: 13, color: "#94A3B8" }}>
        Showing {(currentPage - 1) * rowsPerPage + 1}–
        {Math.min(currentPage * rowsPerPage, data.length)} of {data.length} users
      </span>
      <div style={{ display: "flex", gap: 6, alignItems: "center" }}>
        <PageBtn label="←" disabled={currentPage === 1} onClick={() => setCurrentPage((p) => Math.max(p - 1, 1))} />
        {pageNumbers[0] > 1 && (<>
          <PageBtn label="1" onClick={() => setCurrentPage(1)} />
          {pageNumbers[0] > 2 && <span style={{ padding: "0 4px", color: "#94A3B8" }}>…</span>}
        </>)}
        {pageNumbers.map((p) => (
          <PageBtn key={p} label={String(p)} active={p === currentPage} onClick={() => setCurrentPage(p)} />
        ))}
        {pageNumbers[pageNumbers.length - 1] < totalPages && (<>
          {pageNumbers[pageNumbers.length - 1] < totalPages - 1 && (
            <span style={{ padding: "0 4px", color: "#94A3B8" }}>…</span>
          )}
          <PageBtn label={String(totalPages)} onClick={() => setCurrentPage(totalPages)} />
        </>)}
        <PageBtn label="→" disabled={currentPage === totalPages}
          onClick={() => setCurrentPage((p) => Math.min(p + 1, totalPages))} />
      </div>
    </div>
  );

  return (
    <>
      {/* ── Detail Drawer ── */}
      <UserDetailDrawer
        user={selectedUser}
        onClose={() => setSelectedUser(null)}
        onSuspend={(u) => { onSuspendUser?.(u); setSelectedUser(null); }}
      />

      {/* ── Mobile card list ── */}
      {isMobile ? (
        <div style={{ fontFamily: "'DM Sans', 'Helvetica Neue', sans-serif" }}>
          {paginatedData.length === 0 ? (
            <div style={{ padding: 40, textAlign: "center", color: "#94A3B8" }}>No users found</div>
          ) : paginatedData.map((user, idx) => (
            <MobileCard
              key={user.id}
              user={user}
              idx={(currentPage - 1) * rowsPerPage + idx + 1}
              onRowClick={handleRowClick}
              onSuspend={(u) => onSuspendUser?.(u)}
            />
          ))}
          {pagination}
        </div>
      ) : (

        /* ── Desktop table ── */
        <div style={{
          fontFamily: "'DM Sans', 'Helvetica Neue', sans-serif",
          width: "100%", display: "flex", flexDirection: "column",
          background: "#fff", borderRadius: 16,
          border: "1px solid #E8EDF2",
          boxShadow: "0 1px 4px rgba(15,23,42,0.06)", overflow: "hidden",
        }}>
          <div style={{ overflowX: "auto", width: "100%" }}>
            <table style={{ width: "100%", borderCollapse: "collapse", minWidth: 960 }}>
              <thead>
                <tr style={{ background: "#F8FAFC" }}>
                  <th style={{ ...thBase, width: 48 }}>
                    <input type="checkbox" checked={allSelected} onChange={toggleAll}
                      style={{ cursor: "pointer", accentColor: "#EA580C" }} />
                  </th>
                  <th style={{ ...thBase, width: 72 }}>Sr. No.</th>
                  {sortTh("name", "Username")}
                  {columns.map((col) => (
                    <th key={String(col.key)} style={{ ...thBase, cursor: "pointer" }} onClick={() => onSort(col.key)}>
                      <div style={thInner}>
                        {col.label}
                        <SortIcon active={sortConfig?.key === col.key}
                          direction={sortConfig?.key === col.key ? sortConfig.direction : undefined} />
                      </div>
                    </th>
                  ))}
                  {sortTh("location_allowed", "Status")}
                  {sortTh("created_at", "Joined Date")}
                  <th style={{ ...thBase, textAlign: "right" }}>Action</th>
                </tr>
              </thead>

              <tbody>
                {paginatedData.length === 0 ? (
                  <tr>
                    <td colSpan={columns.length + 6}
                      style={{ padding: "48px 0", textAlign: "center", color: "#94A3B8", fontSize: 14 }}>
                      No users found
                    </td>
                  </tr>
                ) : paginatedData.map((user, idx) => {
                  const status = deriveStatus(user);
                  const globalIdx = (currentPage - 1) * rowsPerPage + idx + 1;
                  const isSelected = selectedIds.has(user.id);

                  return (
                    <tr key={user.id}
                      onClick={() => handleRowClick(user)}
                      style={{ background: isSelected ? "#FFF7ED" : "#fff",
                        transition: "background 0.12s", cursor: "pointer" }}
                      onMouseEnter={(e) => { if (!isSelected) e.currentTarget.style.background = "#FAFBFC"; }}
                      onMouseLeave={(e) => { e.currentTarget.style.background = isSelected ? "#FFF7ED" : "#fff"; }}
                    >
                      <td style={tdBase} onClick={(e) => e.stopPropagation()}>
                        <input type="checkbox" checked={isSelected} onChange={() => toggleOne(user.id)}
                          style={{ cursor: "pointer", accentColor: "#EA580C" }} />
                      </td>
                      <td style={{ ...tdBase, color: "#94A3B8", fontSize: 13 }}>
                        {String(globalIdx).padStart(2, "0")}
                      </td>
                      <td style={tdBase}>
                        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                          <Avatar src={user.image_url} name={user.name} size={36} />
                          <div>
                            <div style={{ fontWeight: 600, fontSize: 14, color: "#0F172A" }}>
                              {user.name || "—"}
                            </div>
                            {user.professional_headline && (
                              <div style={{ fontSize: 11, color: "#94A3B8", marginTop: 1 }}>
                                {user.professional_headline}
                              </div>
                            )}
                          </div>
                        </div>
                      </td>
                      {columns.map((col) => {
                        const val = user[col.key];
                        let display: React.ReactNode = <span style={{ color: "#CBD5E1" }}>—</span>;
                        if (val !== null && val !== undefined && val !== "") {
                          if (Array.isArray(val)) display = val.length ? val.join(", ") : display;
                          else if (typeof val === "boolean") display = val ? "Yes" : "No";
                          else display = String(val);
                        }
                        return (
                          <td key={String(col.key)} style={{ ...tdBase, color: "#475569" }}>{display}</td>
                        );
                      })}
                      <td style={tdBase}><StatusBadge status={status} /></td>
                      <td style={{ ...tdBase, color: "#475569", whiteSpace: "nowrap" }}>
                        {user.created_at
                          ? new Date(user.created_at).toLocaleDateString("en-GB")
                          : <span style={{ color: "#CBD5E1" }}>—</span>}
                      </td>
                      <td style={{ ...tdBase, textAlign: "right" }} onClick={(e) => e.stopPropagation()}>
                        <div style={{ display: "flex", gap: 8, justifyContent: "flex-end" }}>
                          <IconBtn title="View details" onClick={(e) => { e.stopPropagation(); handleRowClick(user); }}>
                            <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
                              <circle cx="8" cy="8" r="7" stroke="#94A3B8" strokeWidth="1.5" />
                              <path d="M8 7v4" stroke="#94A3B8" strokeWidth="1.5" strokeLinecap="round" />
                              <circle cx="8" cy="5" r="0.75" fill="#94A3B8" />
                            </svg>
                          </IconBtn>
                          <IconBtn
                            title={status === "suspended" ? "Unsuspend user" : "Suspend user"}
                            onClick={(e) => { e.stopPropagation(); onSuspendUser?.(user); }}
                          >
                            <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
                              <circle cx="8" cy="8" r="7" stroke="#94A3B8" strokeWidth="1.5" />
                              <path d="M3.5 3.5l9 9" stroke="#94A3B8" strokeWidth="1.5" strokeLinecap="round" />
                            </svg>
                          </IconBtn>
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
          {pagination}
        </div>
      )}
    </>
  );
};

/* ─── Style constants ────────────────────────────────────────── */
const thBase: React.CSSProperties = {
  padding: "13px 16px", textAlign: "left",
  borderBottom: "1px solid #E8EDF2", color: "#64748B",
  fontWeight: 500, fontSize: 13, userSelect: "none", whiteSpace: "nowrap",
};

const thInner: React.CSSProperties = { display: "flex", alignItems: "center", gap: 6 };

const tdBase: React.CSSProperties = {
  padding: "14px 16px", borderBottom: "1px solid #F1F5F9",
  fontSize: 14, verticalAlign: "middle",
};
